<script lang="ts">
 import {zh} from './zh';
 import AriaModeToolbar from './AriaModeToolbar.svelte';import AriaSymbol from './AriaSymbol.svelte';import AriaRhythmTools from './AriaRhythmTools.svelte';import AriaContextTools from './AriaContextTools.svelte';import AriaKeyboard from './AriaKeyboard.svelte';
 import {repeats,textTools,expressions,layoutTools,moreTools,type AriaTool} from './tools';import type {AriaCategory} from './reference';
 import type {Snippet} from 'svelte';
 let {category,phone,landscape,width,busy,hasSelection,pitch,chordPitches=[],flats=false,noteInput,voice,more,canUndo,canRedo,selected,oncategory,onaction,onpitch,onmore,subpanel}:{category:AriaCategory;phone:boolean;landscape:boolean;width:number;busy:boolean;hasSelection:boolean;pitch?:number;chordPitches?:number[];flats?:boolean;noteInput:boolean;voice:number;more:boolean;canUndo:boolean;canRedo:boolean;selected:(id:string)=>boolean;oncategory:(c:AriaCategory)=>void;onaction:(tool:AriaTool,event?:MouseEvent)=>void;onpitch:(p:number)=>void;onmore:()=>void;subpanel:Snippet}=$props();
 const keyboardEnabled=$derived(noteInput||hasSelection);
 const standardKeyboard=$derived(!['chord','lyrics','fingering'].includes(category));
 const phoneKeyboard=$derived(['notes','select'].includes(category));
 const items=$derived(category==='repeats'?repeats:category==='text'?textTools:category==='expression'?expressions:category==='layout'?layoutTools:moreTools);
 function action(id:string){onaction({id});}
</script>
{#snippet pair(kind:'undo'|'navigation')}
 <div class="side-pair" class:landscape><button aria-label={zh(kind==='undo'?'Undo':'Select Next')} disabled={busy||(kind==='undo'?!canUndo:!hasSelection)} onclick={()=>action(kind==='undo'?'action://notation/undo':'select-next-chord')}><AriaSymbol name={kind==='undo'?'arrow.uturn.backward':'chevron.right'} size={landscape?16:17}/></button><span></span><button aria-label={zh(kind==='undo'?'Redo':'Select Previous')} disabled={busy||(kind==='undo'?!canRedo:!hasSelection)} onclick={()=>action(kind==='undo'?'action://notation/redo':'select-prev-chord')}><AriaSymbol name={kind==='undo'?'arrow.uturn.forward':'chevron.left'} size={landscape?16:17}/></button></div>
{/snippet}
{#snippet detail()}
 {#if ['notes','select'].includes(category)}<AriaRhythmTools {phone} {landscape} {more} {selected} enabled={!busy&&(hasSelection||noteInput)} {onaction} {onmore}/>{:else if ['chord','lyrics','fingering'].includes(category)}{@render subpanel()}{:else}<AriaContextTools {items} {phone} enabled={!busy&&(hasSelection||['layout','more'].includes(category))} {selected} {onaction}/>{/if}
{/snippet}
{#snippet piano()}
 <div class="piano-row" class:phone class:landscape>
  {#if phone}{@render pair('undo')}{:else}<div class="pitch-nudge"><small>半音</small><div><button aria-label="升高半音" disabled={!keyboardEnabled} onclick={()=>action('pitch-up')}><AriaSymbol name="arrowtriangle.up.fill" size={16}/></button><span></span><button aria-label="降低半音" disabled={!keyboardEnabled} onclick={()=>action('pitch-down')}><AriaSymbol name="arrowtriangle.down.fill" size={16}/></button></div></div>{/if}
  <div class="wide-keyboard"><AriaKeyboard {flats} {phone} {landscape} enabled={keyboardEnabled} activePitch={pitch} activePitches={chordPitches} follow={!noteInput&&!busy} {onpitch}/></div>
