 </div>
{/snippet}
<section class="aria-entry-surface" class:phone class:landscape class:submode={!standardKeyboard}>
 {#if !phone}
  <div class="tablet-top-menu" class:tight={width<1000}>
   <div class="top-left" style:width={category==='notes'?'152px':'126px'}>{#if category==='notes'}<button class="voice-chip" aria-label={zh('Voice '+voice)} disabled={busy} onclick={e=>onaction({id:'voices',menu:[1,2,3,4].filter(v=>v!==voice).map(v=>({id:'voice-'+v,label:'Voice '+v}))},e)}>{voice}</button>{/if}<button aria-label="撤销" disabled={!canUndo||busy} onclick={()=>action('action://notation/undo')}><AriaSymbol name="arrow.uturn.backward" size={17}/></button><button aria-label="重做" disabled={!canRedo||busy} onclick={()=>action('action://notation/redo')}><AriaSymbol name="arrow.uturn.forward" size={17}/></button></div>
   <AriaModeToolbar {category} tight={width<1000} {busy} onselect={oncategory}/>
   <div class="top-right" style:width={category==='notes'?'152px':'126px'}><button aria-label="选择前一项" disabled={!hasSelection||busy} onclick={()=>action('select-prev-chord')}><AriaSymbol name="chevron.left" size={17}/></button><button aria-label="选择后一项" disabled={!hasSelection||busy} onclick={()=>action('select-next-chord')}><AriaSymbol name="chevron.right" size={17}/></button><button aria-label="删除选区" disabled={!hasSelection||busy} onclick={()=>action('action://notation/delete')}><AriaSymbol name="trash" size={17}/></button></div>
  </div>
  <div class="tablet-detail">{@render detail()}</div>
  {#if standardKeyboard}{@render piano()}{/if}
 {:else}
  {#if ['chord','fingering'].includes(category)}<div class="phone-mode-bar above"><AriaModeToolbar {category} compact {busy} onselect={oncategory}/></div>{/if}
  {#if category==='lyrics'}<header class="lyrics-header"><strong>歌词</strong><button onclick={()=>oncategory('text')}>完成</button></header>{/if}
  {#if landscape&&phoneKeyboard}<div class="phone-landscape-controls"><div class="landscape-options"><AriaRhythmTools phone landscape sections="options" {more} {selected} enabled={!busy&&(hasSelection||noteInput)} {onaction} {onmore}/></div><div class="landscape-input"><AriaRhythmTools phone landscape sections="duration" {selected} enabled={!busy&&(hasSelection||noteInput)} {onaction} {onmore}/>{@render piano()}</div></div>
  {:else}<div class="phone-detail">{@render detail()}</div>{#if phoneKeyboard}<div class="phone-piano">{@render piano()}</div>{/if}{/if}
  {#if !['chord','fingering'].includes(category)}<div class="phone-mode-bar"><AriaModeToolbar {category} compact {busy} onselect={oncategory}/></div>{/if}
 {/if}
</section>
