one;width:36px;height:80px;border:.5px solid var(--aria-fill);border-radius:10px;background:color-mix(in srgb, var(--aria-surface) 55%, transparent);display:flex;flex-direction:column;align-items:center;justify-content:center;}.side-pair>button{flex:1;min-height:0;width:38px;padding:0;background:none;border:0;display:grid;place-items:center;}.side-pair>span{height:1px;width:24px;flex:none;background:var(--aria-line);}.side-pair.landscape{height:76px;border-radius:8px;background:color-mix(in srgb, var(--aria-surface) 70%, transparent);}.phone-mode-bar{padding:4px 4px 2px;border-top:.5px solid var(--aria-line);background:color-mix(in srgb, var(--aria-surface) 22%, transparent);}.phone-mode-bar.above{padding-block:4px;border-top:0;border-bottom:.5px solid var(--aria-line);}.phone-landscape-controls{display:flex;gap:10px;padding:6px;}.landscape-options{flex:0 1 370px;min-width:300px;max-width:430px;height:190px;}.landscape-input{flex:1;min-width:0;}.landscape-input .piano-row{gap:8px;}.landscape-input .wide-keyboard{height:92px;}.lyrics-header{display:flex;align-items:center;justify-content:space-between;padding:8px 8px 4px;}.lyrics-header strong{font-size:16px;}.lyrics-header button{background:none;border:0;color:var(--aria-active);padding:6px 12px;font-size:15px;font-weight:600;}button:disabled{opacity:.38;}
